catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    if (newValue == 'trade_level') {
        g_form.clearOptions('outcome'); //clear all options
        g_form.addOption('outcome', '', '-- None --');
        g_form.addOption('outcome', 'Process Trade Cancellation', 'Process Trade Cancellation');
        g_form.addOption('outcome', 'Put Trade On-Hold', 'Put Trade On-Hold');

    }

    if (newValue == 'bulk_level') {
        g_form.clearOptions('outcome'); //clear all options
        g_form.addOption('outcome', '', '-- None --');
        g_form.addOption('outcome', 'Confirm Trade', 'Confirm Trade');
        g_form.addOption('outcome', 'Settle Trade', 'Settle Trade');
        g_form.addOption('outcome', 'Put Trade On-Hold', 'Put Trade On-Hold');
        g_form.addOption('outcome', 'Process Trade Cancellation', 'Process Trade Cancellation');
        g_form.addOption('outcome', 'Resume Trade', 'Resume Trade');
        //g_form.addOption('outcome', 'Amend Trade', 'Amend Trade'); commented since out of scope
    }

}
